  const TALES = [
  /* ---------------- A1 ---------------- */
  { id:'lion', lv:'A1', t:'The Lion and the Mouse', ic:'🦁', focus:'Present simple · can / can\'t', names:{ A:'Lion', B:'Mouse' }, g:{ A:'male', B:'female' },
    words:[['hungry','och'],['small','kichik'],['help','yordam bermoq'],['catch','tutmoq'],['worry','xavotirlanmoq'],['friend',"do'st"]],
    lines:[
      ['N','A big lion is sleeping under a tree.','Katta sher daraxt tagida uxlayapti.'],
      ['N','A little mouse runs on his nose.','Kichkina sichqon uning burni ustida yuguradi.'],
      ['N','The lion wakes up. He is very angry.',"Sher uyg'onadi. U juda jahldor."],
      ['A','I am hungry. I want to eat you!','Men ochman. Seni yemoqchiman!'],
      ['B','Please, don\'t eat me! I am very small. One day I can help you.','Iltimos, meni yemang! Men juda kichkinaman. Bir kun sizga yordam bera olaman.'],
      ['A','Ha ha! You are so small. How can you help me? OK, go home.','Ha-ha! Sen juda kichkinasan. Menga qanday yordam berasan? Mayli, uyingga bor.'],
      ['N','Next week, hunters catch the lion in a big net.',"Keyingi hafta ovchilar sherni katta to'rga tutishadi."],
      ['A','Help! Help! I can\'t get out!','Yordam bering! Chiqa olmayapman!'],
      ['N','The little mouse hears him and runs to the net.',"Kichkina sichqon uni eshitadi va to'rga yuguradi."],
      ['B','Don\'t worry. I can help you!','Xavotir olmang. Men yordam bera olaman!'],
      ['N','She bites the net again and again. Now there is a big hole.',"U to'rni qayta-qayta tishlaydi. Endi katta teshik bor."],
      ['A','Thank you, my little friend! Small friends can be great friends.',"Rahmat, kichkina do'stim! Kichik do'stlar ham buyuk do'st bo'la oladi."]],
    qs:[['Where is the lion sleeping?','Sher qayerda uxlayapti?','Under a tree.'],['How does the mouse help the lion?','Sichqon sherga qanday yordam beradi?','She bites the net and makes a hole.'],['What is the lesson of the story?','Ertakning saboqi nima?','Small friends can be great friends.']] },

  { id:'pigs', lv:'A1', t:'The Three Little Pigs', ic:'🐷', fun:1, focus:'Present simple · let me', names:{ A:'Wolf', B:'Little Pig' }, g:{ A:'male', B:'female' },
    words:[['build','qurmoq'],['easy','oson'],['slow','sekin'],['fall',"yiqilmoq"],['strong','mustahkam'],['tired','charchagan']],
    lines:[
      ['N','Three little pigs leave home. They want to build houses.',"Uchta kichkina cho'chqacha uydan chiqadi. Ular uy qurmoqchi."],
      ['N','The first pig builds a house of straw. It is fast and easy.',"Birinchi cho'chqacha somondan uy quradi. Bu tez va oson."],
      ['N','The second pig builds a house of sticks.',"Ikkinchisi cho'plardan uy quradi."],
      ['N','The third pig builds a house of bricks. It is slow, hard work.',"Uchinchisi g'ishtdan uy quradi. Bu sekin va og'ir ish."],
      ['N','Then a big bad wolf comes to the straw house.',"Keyin katta yovuz bo'ri somon uyga keladi."],
      ['A','Little pig, little pig, let me come in!',"Cho'chqacha, cho'chqacha, meni ichkariga kirit!"],
      ['B','No, no, never!',"Yo'q, yo'q, hech qachon!"],
      ['A','Then I\'ll huff and I\'ll puff and I\'ll blow your house down!',"Unda puflayman, puflayman va uyingni uchirib yuboraman!"],
      ['N','Whoosh! The straw house falls. The stick house falls too. The pigs run to the brick house.',"Vush! Somon uy yiqiladi. Cho'p uy ham yiqiladi. Cho'chqachalar g'isht uyga yuguradi."],
      ['N','The wolf huffs and puffs and puffs. But the brick house doesn\'t fall.',"Bo'ri puflaydi, puflaydi, puflaydi. Lekin g'isht uy yiqilmaydi."],
      ['A','Oh no! I\'m so tired!','Voy! Juda charchadim!'],
      ['N','The wolf goes away, and the three pigs sing and dance in their strong house.',"Bo'ri ketadi, uchta cho'chqacha esa mustahkam uyida qo'shiq aytib, raqs tushadi."],
      ['B','Hard work is good work!',"Og'ir mehnat — yaxshi mehnat!"]],
    qs:[['What are the three houses made of?','Uchta uy nimadan qurilgan?','Straw, sticks and bricks.'],['Why doesn\'t the brick house fall?',"G'isht uy nega yiqilmaydi?",'Because it is strong.'],['Which pig is the smartest? Why?',"Qaysi cho'chqacha eng aqlli? Nega?",'The third pig, because he works hard.']] },

  { id:'hare', lv:'A1', t:'The Tortoise and the Hare', ic:'🐢', focus:'Present simple · adverbs (fast, slowly)', names:{ A:'Hare', B:'Tortoise' }, g:{ A:'male', B:'female' },
    words:[['fast','tez'],['race','poyga'],['laugh at','ustidan kulmoq'],['stop',"to'xtamoq"],['already','allaqachon'],['win','yutmoq']],
    lines:[
      ['N','The hare is very fast. He likes to laugh at the slow tortoise.',"Quyon juda tez. U sekin toshbaqa ustidan kulishni yaxshi ko'radi."],
      ['A','You are so slow! You walk like a stone!','Sen juda sekinsan! Tosh kabi yurasan!'],
      ['B','OK. Let\'s have a race.','Mayli. Keling, poyga qilamiz.'],
      ['A','A race? With me? Ha ha! OK, let\'s go!','Poyga? Men bilanmi? Ha-ha! Mayli, ketdik!'],
      ['N','The race starts. The hare runs very fast. The tortoise walks slowly.','Poyga boshlanadi. Quyon juda tez yuguradi. Toshbaqa sekin yuradi.'],
      ['N','The hare looks back. He can\'t see the tortoise.',"Quyon orqasiga qaraydi. U toshbaqani ko'ra olmaydi."],
      ['A','I have a lot of time. I can sleep a little.',"Vaqtim ko'p. Biroz uxlasam bo'ladi."],
      ['N','He sleeps under a tree. The tortoise walks and walks. She never stops.',"U daraxt tagida uxlaydi. Toshbaqa yuradi va yuradi. U hech qachon to'xtamaydi."],
      ['N','The hare wakes up. The sun is low. He runs to the finish...',"Quyon uyg'onadi. Quyosh botyapti. U marraga yuguradi..."],
      ['N','But the tortoise is already there! All the animals are clapping.',"Lekin toshbaqa allaqachon o'sha yerda! Hamma hayvonlar qarsak chalyapti."],
      ['B','Slow and steady wins the race!',"Sekin, lekin to'xtamay yurgan yutadi!"]],
    qs:[['Why does the hare sleep?','Quyon nega uxlaydi?','Because he thinks he has a lot of time.'],['Who wins the race?','Poygada kim yutadi?','The tortoise wins.'],['What do you do slowly but every day?',"Siz nimani sekin, lekin har kuni qilasiz?",'I study English a little every day.']] },

  { id:'ginger', lv:'A1', t:'The Gingerbread Man', ic:'🍪', fun:1, focus:'Imperatives · can\'t', names:{ A:'Gingerbread Man', B:'Old Woman', C:'Fox' }, g:{ A:'male', B:'female', C:'male' },
    words:[['run away','qochib ketmoq'],['catch','tutmoq'],['swim','suzmoq'],['river','daryo'],['deep','chuqur'],['trust','ishonmoq'],['delicious','mazali']],
    lines:[
      ['N','An old woman makes a gingerbread man. She opens the oven...','Bir kampir pechenye-odamcha yasaydi. U pechni ochadi...'],
      ['N','And the gingerbread man jumps out and runs away!','Pechenye-odamcha sakrab chiqib, qochib ketadi!'],
      ['B','Stop! Stop! Come back!',"To'xta! To'xta! Qayt!"],
      ['A','Run, run, as fast as you can! You can\'t catch me, I\'m the Gingerbread Man!','Yugur, yugur, bor kuching bilan! Meni tutolmaysan, men Pechenye-odamchaman!'],
      ['N','He runs past a cow, a horse and some farmers. Nobody can catch him.',"U sigir, ot va dehqonlar yonidan yugurib o'tadi. Hech kim uni tutolmaydi."],
      ['N','Then he comes to a river. He can\'t swim.','Keyin u daryoga yetib keladi. U suzolmaydi.'],
      ['C','Hello, little man. Jump on my tail. I can take you across.',"Salom, kichkina odam. Dumimga sakra. Seni narigi qirg'oqqa olib o'taman."],
      ['N','The gingerbread man jumps on the fox\'s tail. The water is deep.','Pechenye-odamcha tulkining dumiga sakraydi. Suv chuqur.'],
      ['C','Oh, the water is high! Jump on my nose!','Voy, suv baland! Burnimga sakra!'],
      ['N','He jumps on the fox\'s nose... and SNAP! The fox eats him.','U tulkining burniga sakraydi... va QARS! Tulki uni yeb qo\'yadi.'],
      ['C','Mmm. Delicious! Never trust a smiling fox!','Mmm. Mazali! Jilmaygan tulkiga hech qachon ishonma!']],
    qs:[['Who can\'t catch the gingerbread man?','Pechenye-odamchani kim tutolmaydi?','The old woman, a cow, a horse and the farmers.'],['Why does he need the fox?','Unga tulki nega kerak?','Because he can\'t swim.'],['What is the lesson?','Saboq nima?','Don\'t trust everyone.']] },

  { id:'afandi-ring', lv:'A1', t:'Afandi Looks for His Ring', ic:'💍', fun:1, focus:'Present continuous · questions', names:{ A:'Afandi', B:'Neighbour' }, g:{ A:'male', B:'female' },
    words:[['look for','qidirmoq'],['find','topmoq'],['lose',"yo'qotmoq"],['ring','uzuk'],['dark',"qorong'i"],['light',"yorug'lik"],['neighbour',"qo'shni"]],
    lines:[
      ['N','It is night. Afandi is in the street under a lamp. He is looking for something.','Tun. Afandi ko\'chada, chiroq tagida. U nimanidir qidiryapti.'],
      ['B','Afandi, what are you looking for?','Afandi, nima qidiryapsiz?'],
      ['A','My ring. It is a gold ring. I can\'t find it.','Uzugimni. Tilla uzuk. Topa olmayapman.'],
      ['B','Oh no! I can help you.','Voy! Men yordam beraman.'],
      ['N','They look and look for a long time. They can\'t find the ring.','Ular uzoq qidirishadi. Uzukni topisholmaydi.'],
      ['B','Afandi, where did you lose it? Here, under the lamp?',"Afandi, uni qayerda yo'qotdingiz? Shu yerda, chiroq tagidami?"],
      ['A','No, I lost it in my house.',"Yo'q, uyimda yo'qotdim."],
      ['B','In your house?! Then why are you looking here?','Uyingizdami?! Unda nega bu yerda qidiryapsiz?'],
      ['A','Because my house is dark. Here there is light!',"Chunki uyim qorong'i. Bu yerda esa yorug'!"],
      ['N','The neighbour laughs and laughs. Afandi is still looking under the lamp.',"Qo'shni kulaveradi. Afandi esa hali ham chiroq tagida qidiryapti."]],
    qs:[['What is Afandi looking for?','Afandi nima qidiryapti?','His gold ring.'],['Where did he lose it?',"U uni qayerda yo'qotgan?",'In his house.'],['Why is he looking under the lamp?','Nega chiroq tagida qidiryapti?','Because there is light there.']] },

  /* ---------------- A2 ---------------- */
  { id:'wolf', lv:'A2', t:'The Boy Who Cried Wolf', ic:'🐺', focus:'Past simple (was, ran, came, did)', names:{ A:'Boy', B:'Villager' }, g:{ A:'male', B:'female' },
    words:[['bored','zerikkan'],['trick','aldamoq'],['again','yana'],['real','haqiqiy'],['lie',"yolg'on gapirmoq"],['believe','ishonmoq'],['truth','haqiqat']],
    lines:[
      ['N','Once there was a young shepherd. Every day he watched the sheep on a hill near his village.',"Bir bor ekan, bir yosh cho'pon bor ekan. U har kuni qishloq yonidagi tepalikda qo'ylarni boqardi."],
      ['N','He was bored. One day he had an idea.',"U zerikardi. Bir kuni uning xayoliga bir fikr keldi."],
      ['A','Wolf! Wolf! Help! A wolf is eating the sheep!',"Bo'ri! Bo'ri! Yordam bering! Bo'ri qo'ylarni yeyapti!"],
      ['N','All the villagers ran up the hill. But there was no wolf.',"Barcha qishloqdoshlar tepalikka yugurib chiqishdi. Lekin bo'ri yo'q edi."],
      ['A','Ha ha! I tricked you!','Ha-ha! Sizlarni aldadim!'],
      ['B','That isn\'t funny. Don\'t do it again!','Bu kulgili emas. Boshqa bunday qilma!'],
      ['N','But the next week he did it again. Again the villagers came, and again there was no wolf.',"Lekin keyingi hafta u yana shunday qildi. Odamlar yana keldi va yana bo'ri yo'q edi."],
      ['N','Then one evening a real wolf came out of the forest.',"Keyin bir kuni kechqurun o'rmondan haqiqiy bo'ri chiqdi."],
      ['A','Wolf! Wolf! Please help me! This time it\'s true!',"Bo'ri! Bo'ri! Iltimos, yordam bering! Bu safar rost!"],
      ['B','He\'s lying again. Let\'s stay at home.',"U yana yolg'on gapiryapti. Uyda qolaylik."],
      ['N','Nobody came. The wolf chased the sheep away, and the boy cried all night.',"Hech kim kelmadi. Bo'ri qo'ylarni haydab ketdi, bola esa tun bo'yi yig'ladi."],
      ['B','When you tell lies, people don\'t believe you, even when you tell the truth.',"Yolg'on gapirsang, rost gapirganingda ham odamlar senga ishonmaydi."]],
    qs:[['Why did the boy shout "Wolf!" the first time?','Bola birinchi marta nega "Bo\'ri!" deb baqirdi?','Because he was bored.'],['Why didn\'t the villagers come at the end?','Oxirida odamlar nega kelmadi?','They thought he was lying again.'],['Tell me about a time when someone didn\'t believe you.','Kimdir sizga ishonmagan bir holat haqida gapiring.','Once I told my friend the truth, but he didn\'t believe me.']] },

  { id:'crow', lv:'A2', t:'The Fox and the Crow', ic:'🦊', fun:1, focus:'Past simple · compliments (You look…)', names:{ A:'Fox', B:'Crow' }, g:{ A:'female', B:'male' },
    words:[['piece',"bo'lak"],['wonderful','ajoyib'],['proud','faxrlangan'],['voice','ovoz'],['terrible','dahshatli'],['sure','amin, ishonchli']],
    lines:[
      ['N','One morning a crow found a big piece of cheese. He flew up into a tree to eat it.',"Bir kuni ertalab qarg'a katta bo'lak pishloq topdi. Uni yeyish uchun daraxtga uchib chiqdi."],
      ['N','A hungry fox saw him and wanted the cheese.',"Och tulki uni ko'rdi va pishloqni xohladi."],
      ['A','Good morning, Mr Crow! You look wonderful today!',"Xayrli tong, Qarg'a janoblari! Bugun ajoyib ko'rinyapsiz!"],
      ['N','The crow said nothing. He held the cheese in his beak.',"Qarg'a hech narsa demadi. U pishloqni tumshug'ida ushlab turdi."],
      ['A','Your feathers are so shiny and black. You are the most beautiful bird in the forest!',"Patlaringiz juda yaltiroq va qop-qora. Siz o'rmondagi eng chiroyli qushsiz!"],
      ['A','I\'m sure your voice is beautiful too. Please, sing a song for me!',"Ovozingiz ham chiroyli ekaniga aminman. Iltimos, men uchun bir qo'shiq kuylang!"],
      ['N','The crow felt very proud. He opened his beak and sang: CAW! CAW! CAW!',"Qarg'a o'zidan juda faxrlandi. U tumshug'ini ochdi va kuyladi: QAR! QAR! QAR!"],
      ['N','The cheese fell down, and the fox caught it.',"Pishloq pastga tushdi, tulki esa uni ilib oldi."],
      ['A','Thank you! Your voice is terrible, but your cheese is delicious!',"Rahmat! Ovozingiz dahshatli, lekin pishlog'ingiz mazali!"],
      ['B','Oh no! I was so stupid!',"Voy! Qanday ahmoq bo'ldim!"],
      ['N','Remember: don\'t trust people who say too many nice things.',"Yodda tuting: haddan ortiq shirin gap aytadiganlarga ishonmang."]],
    qs:[['What did the crow find?',"Qarg'a nima topdi?",'A big piece of cheese.'],['Why did the crow open his beak?',"Qarg'a nega tumshug'ini ochdi?",'Because he wanted to sing for the fox.'],['Do you like compliments? Why?','Maqtovni yoqtirasizmi? Nega?','Yes, but I am careful with too many compliments.']] },

  { id:'bears', lv:'A2', t:'Goldilocks and the Three Bears', ic:'🐻', focus:'too + adjective · past simple', names:{ A:'Goldilocks', B:'Father Bear', C:'Baby Bear' }, g:{ A:'female', B:'male', C:'female' },
    words:[['too hot','juda issiq'],['just right','aynan joyida'],['break','sindirmoq'],['fall asleep','uxlab qolmoq'],['scream','qichqirmoq'],['stranger','begona']],
    lines:[
      ['N','Once upon a time, three bears lived in a little house in the forest.',"Bir bor ekan, o'rmondagi kichkina uyda uchta ayiq yashar ekan."],
      ['N','One morning their porridge was too hot, so they went for a walk.',"Bir kuni ertalab bo'tqalari juda issiq edi, shuning uchun ular sayrga chiqishdi."],
      ['N','A girl called Goldilocks found the house. The door was open, so she walked in.',"Oltinsoch ismli qiz uyni topib oldi. Eshik ochiq edi, u ichkariga kirdi."],
      ['A','Mmm, porridge! This one is too hot. This one is too cold. This one is just right!',"Mmm, bo'tqa! Bunisi juda issiq. Bunisi juda sovuq. Bunisi esa aynan joyida!"],
      ['N','She ate all of Baby Bear\'s porridge. Then she sat on his little chair, and it broke!',"U ayiqchaning bo'tqasini butunlay yeb qo'ydi. Keyin uning kichkina kursisiga o'tirdi va kursi sinib ketdi!"],
      ['N','She was tired, so she went upstairs and fell asleep in the smallest bed.',"U charchagan edi, yuqoriga chiqib, eng kichik karavotda uxlab qoldi."],
      ['N','Soon the bears came home.',"Tez orada ayiqlar uyga qaytishdi."],
      ['B','Somebody ate my porridge!','Kimdir mening bo\'tqamni yebdi!'],
      ['C','Somebody ate MY porridge, and they broke my chair!',"Kimdir MENING bo'tqamni yebdi, kursimni ham sindiribdi!"],
      ['C','And look! Somebody is sleeping in my bed!','Qarang! Kimdir karavotimda uxlayapti!'],
      ['N','Goldilocks woke up, saw three bears and screamed. She jumped out of the window and ran home.',"Oltinsoch uyg'onib, uchta ayiqni ko'rdi va qichqirdi. Derazadan sakrab, uyiga yugurdi."],
      ['A','I will never go into a stranger\'s house again!',"Begona uyga boshqa hech qachon kirmayman!"]],
    qs:[['Why did the bears go for a walk?','Ayiqlar nega sayrga chiqishdi?','Because their porridge was too hot.'],['What happened to Baby Bear\'s chair?','Ayiqchaning kursisiga nima bo\'ldi?','It broke.'],['How do you like your tea: too hot, too cold or just right?',"Choyni qanday yoqtirasiz?",'I like it hot, but not too hot.']] },

  { id:'ant', lv:'A2', t:'The Ant and the Grasshopper', ic:'🐜', focus:'should · past simple', names:{ A:'Grasshopper', B:'Ant' }, g:{ A:'male', B:'female' },
    words:[['carry','tashimoq'],['save',"yig'ib qo'ymoq"],['should','kerak (maslahat)'],['knock','taqillatmoq'],['snow','qor'],['everywhere','hamma joyda']],
    lines:[
      ['N','All summer the grasshopper played music and sang in the sun.',"Butun yoz chigirtka quyosh ostida musiqa chalib, qo'shiq aytdi."],
      ['N','The ant worked hard every day. She carried food to her home.',"Chumoli har kuni tinmay ishladi. U uyiga oziq-ovqat tashidi."],
      ['A','Why are you working? It\'s summer! Come and dance with me!',"Nega ishlayapsan? Yoz-ku! Kel, men bilan raqs tush!"],
      ['B','Winter is coming. I need food for the winter. You should save food too.',"Qish kelyapti. Menga qish uchun ovqat kerak. Sen ham ovqat yig'ib qo'yishing kerak."],
      ['A','Winter? That\'s a long time away. I have lots of food now!',"Qishmi? U hali uzoq. Hozir ovqatim ko'p!"],
      ['N','Then winter came. It was cold, and there was snow everywhere.',"Keyin qish keldi. Sovuq edi, hamma yoq qor edi."],
      ['N','The grasshopper had no food. He was hungry and cold. He knocked on the ant\'s door.',"Chigirtkada ovqat yo'q edi. U och va sovqotgan edi. U chumolining eshigini taqillatdi."],
      ['A','Please, can you give me some food? I\'m so hungry.',"Iltimos, menga ozgina ovqat bera olasanmi? Juda ochman."],
      ['B','What did you do all summer?','Butun yoz nima qilding?'],
      ['A','I sang and played music.',"Qo'shiq aytdim va musiqa chaldim."],
      ['B','Well, come in. You can eat with me. But next summer, you can sing AND work!',"Mayli, kir. Men bilan ovqatlanaver. Lekin keyingi yoz ham kuylaysan, HAM ishlaysan!"],
      ['N','The next summer, the grasshopper worked in the morning and played music in the evening.',"Keyingi yozda chigirtka ertalab ishladi, kechqurun esa musiqa chaldi."]],
    qs:[['What did the grasshopper do all summer?','Chigirtka butun yoz nima qildi?','He played music and sang.'],['What should the grasshopper do next summer?','Chigirtka keyingi yoz nima qilishi kerak?','He should work and save food.'],['What should you save for the future?',"Kelajak uchun nimani yig'ib qo'yishingiz kerak?",'I should save some money every month.']] },

  { id:'afandi-coat', lv:'A2', t:'Eat, My Coat, Eat!', ic:'🧥', fun:1, focus:'Past simple · nobody / nothing / everybody', names:{ A:'Afandi', B:'Rich Man' }, g:{ A:'male', B:'male' },
    words:[['invite','taklif qilmoq'],['wedding',"to'y"],['put on','kiymoq'],['welcome','xush kelibsiz'],['bring','olib kelmoq'],['feed','ovqatlantirmoq'],['nothing','hech narsa']],
    lines:[
      ['N','One day a rich man invited people to a big wedding party. Afandi went in his old work clothes.',"Bir kuni bir boy katta to'yga mehmon chaqirdi. Afandi eski ish kiyimida bordi."],
      ['N','Nobody looked at him. Nobody gave him a seat or any food.',"Unga hech kim qaramadi. Hech kim unga joy ham, ovqat ham bermadi."],
      ['N','So Afandi went home and put on his best coat. It was long and beautiful.',"Shunda Afandi uyiga borib, eng yaxshi to'nini kiydi. U uzun va chiroyli edi."],
      ['N','When he came back, everybody smiled at him.',"U qaytib kelganida hamma unga jilmaydi."],
      ['B','Welcome, welcome, dear Afandi! Please sit here, in the best place!',"Xush kelibsiz, aziz Afandi! Marhamat, to'rga o'ting!"],
      ['N','The servants brought him hot plov, meat and sweets.',"Xizmatkorlar unga issiq palov, go'sht va shirinliklar olib kelishdi."],
      ['N','Afandi took some plov and put it on his coat.',"Afandi bir qoshiq palov olib, to'niga qo'ydi."],
      ['A','Eat, my coat, eat! Have some more!',"Ye, to'nim, ye! Yana ol!"],
      ['B','Afandi! What are you doing? Why are you feeding your coat?',"Afandi! Nima qilyapsiz? Nega to'ningizni ovqatlantiryapsiz?"],
      ['A','An hour ago I came in my old clothes, and you gave me nothing. Now I came in this coat, and you gave me everything. So the food is for the coat, not for me!',"Bir soat oldin eski kiyimda keldim, menga hech narsa bermadingiz. Endi shu to'nda keldim, hammasini berdingiz. Demak, ovqat menga emas, to'nga ekan!"],
      ['N','The rich man\'s face turned red, and everybody laughed.',"Boyning yuzi qizarib ketdi, hamma kulib yubordi."]],
    qs:[['What did Afandi wear the first time?','Afandi birinchi safar nima kiyib bordi?','His old work clothes.'],['Why did Afandi feed his coat?',"Afandi nega to'nini ovqatlantirdi?",'Because people respected his coat, not him.'],['Do people judge others by their clothes in your city?','Shahringizda odamlarni kiyimiga qarab baholashadimi?','Sometimes yes, but it is not right.']] },

  /* ---------------- B1 ---------------- */
  { id:'emperor', lv:'B1', t:'The Emperor\'s New Clothes', ic:'👑', fun:1, focus:'so … that · couldn\'t … either', names:{ A:'Emperor', B:'Weaver', C:'Child' }, g:{ A:'male', B:'female', C:'female' },
    words:[['trickster','firibgar'],['pretend',"o'zini …dek ko'rsatmoq"],['be afraid',"qo'rqmoq"],['either','ham (inkorda)'],['crowd','olomon'],['suddenly','birdan'],['magnificent','hashamatli, ajoyib']],
    lines:[
      ['N','Many years ago there was an emperor who loved new clothes more than anything else. He changed his outfit every hour.',"Ko'p yillar oldin yangi kiyimni hamma narsadan ko'proq yaxshi ko'radigan bir imperator bo'lgan ekan. U har soatda kiyimini almashtirardi."],
      ['N','One day two clever tricksters arrived in the city. They said they were the best weavers in the world.',"Bir kuni shaharga ikki ayyor firibgar keldi. Ular o'zlarini dunyodagi eng zo'r to'quvchilar deyishdi."],
      ['B','Our cloth is magic. It\'s so beautiful that stupid people can\'t see it at all.',"Bizning matomiz sehrli. U shunchalik chiroyliki, ahmoq odamlar uni umuman ko'ra olmaydi."],
      ['A','Wonderful! Then I\'ll know who is clever and who is stupid. Make me a suit at once!',"Ajoyib! Unda kim aqlli, kim ahmoqligini bilib olaman. Darhol menga kostyum tikinglar!"],
      ['N','The emperor gave them bags of gold and silk. They hid it all and pretended to work on empty looms.',"Imperator ularga qop-qop oltin va ipak berdi. Ular hammasini yashirib, bo'sh dastgohlarda ishlayotgandek ko'rsatishdi."],
      ['N','The emperor sent his ministers to check. They saw nothing, but they were afraid to look stupid.',"Imperator tekshirish uchun vazirlarini yubordi. Ular hech narsa ko'rmadi, lekin ahmoq ko'rinishdan qo'rqishdi."],
      ['B','Isn\'t the colour lovely? Feel how light it is!',"Rangi ajoyib emasmi? Qarang, qanchalik yengil!"],
      ['N','Finally the emperor came himself. He couldn\'t see anything either, but he said...',"Nihoyat imperatorning o'zi keldi. U ham hech narsa ko'rmadi, lekin dedi..."],
      ['A','Magnificent! I\'ll wear it in the parade tomorrow.',"Ajoyib! Ertaga paradda kiyaman."],
      ['N','The next day the emperor walked through the streets in his "new clothes". Everyone shouted how beautiful they were.',"Ertasiga imperator 'yangi kiyimida' ko'chalardan o'tdi. Hamma ularni baqirib maqtadi."],
      ['C','But he isn\'t wearing anything!',"Lekin uning ustida hech narsa yo'q-ku!"],
      ['N','Suddenly the whole crowd started laughing. The emperor knew the child was right, but he kept walking with his head held high.',"Birdan butun olomon kula boshladi. Imperator bola haqligini bildi, lekin boshini baland tutib, yurishda davom etdi."]],
    qs:[['Why couldn\'t the ministers say the truth?','Vazirlar nega haqiqatni aytolmadi?','Because they were afraid to look stupid.'],['Who said the truth?','Haqiqatni kim aytdi?','A little child.'],['Have you ever pretended to understand something?',"Biror narsani tushungandek ko'rsatganmisiz?",'Yes, once in a meeting I pretended to understand, but later I asked.']] },

  { id:'jack', lv:'B1', t:'Jack and the Beanstalk', ic:'🌱', focus:'so … that · as … as he could', names:{ A:'Jack', B:'Mother', C:'Giant' }, g:{ A:'male', B:'female', C:'male' },
    words:[['poor','kambag\'al'],['offer','taklif qilmoq'],['deal','savdo, kelishuv'],['grow into','…ga aylanmoq'],['climb','tirmashib chiqmoq'],['hide','yashirinmoq'],['chase','quvmoq']],
    lines:[
      ['N','Jack lived with his mother in a small house. They were so poor that they had only one old cow.',"Jek onasi bilan kichkina uyda yashardi. Ular shunchalik kambag'al ediki, faqat bitta qari sigirlari bor edi."],
      ['B','Jack, take the cow to the market and sell her. Don\'t come back without money!',"Jek, sigirni bozorga olib borib sot. Pulsiz qaytma!"],
      ['N','On the way, Jack met a strange old man who offered him five magic beans for the cow.',"Yo'lda Jek g'alati bir cholni uchratdi. U sigir evaziga beshta sehrli loviya taklif qildi."],
      ['A','Magic beans? Sounds like a great deal!',"Sehrli loviya? Zo'r savdo-ku!"],
      ['B','Beans?! You sold our cow for beans? You silly boy!',"Loviya?! Sigirimizni loviyaga sotdingmi? Ahmoq bola!"],
      ['N','She threw the beans out of the window. During the night they grew into a giant beanstalk that reached the clouds.',"U loviyalarni derazadan uloqtirdi. Tunda ular bulutlarga yetadigan ulkan poyaga aylandi."],
      ['N','Jack climbed up and found a castle in the sky. Inside lived a huge giant.',"Jek tepaga tirmashib chiqdi va osmonda qal'a topdi. Ichida ulkan dev yashardi."],
      ['C','Fee-fi-fo-fum! I smell a human! Where is he?',"Fi-fay-fo-fam! Odam hidi kelyapti! U qayerda?"],
      ['N','Jack hid in the kitchen. When the giant fell asleep, Jack took a hen that laid golden eggs.',"Jek oshxonaga yashirindi. Dev uxlab qolganda, Jek oltin tuxum qo'yadigan tovuqni oldi."],
      ['N','The hen clucked, the giant woke up and chased him. Jack climbed down as fast as he could.',"Tovuq qaqilladi, dev uyg'onib, uni quvdi. Jek bor kuchi bilan pastga tushdi."],
      ['A','Mother! Bring me the axe, quick!',"Ona! Boltani olib keling, tez!"],
      ['N','Jack cut down the beanstalk, and the giant fell with a terrible crash. From then on, Jack and his mother were never poor again.',"Jek poyani chopib tashladi, dev dahshatli gumburlab yiqildi. Shundan beri Jek va onasi hech qachon kambag'al bo'lishmadi."]],
    qs:[['Why was Jack\'s mother angry?','Jekning onasi nega jahli chiqdi?','Because he sold the cow for beans.'],['What did Jack take from the giant?','Jek devdan nimani oldi?','A hen that laid golden eggs.'],['Tell me about a good or bad deal you made.',"Qilgan yaxshi yoki yomon savdoingiz haqida gapiring.",'Last year I bought a cheap phone, but it broke after a month.']] },

  { id:'elves', lv:'B1', t:'The Elves and the Shoemaker', ic:'👞', focus:'poorer and poorer · present perfect (I\'ve never seen)', names:{ A:'Shoemaker', B:'Wife' }, g:{ A:'male', B:'female' },
    words:[['enough','yetarli'],['perfect','mukammal'],['customer','xaridor'],['price','narx'],['find out','bilib olmoq'],['disappear',"g'oyib bo'lmoq"],['luck','omad']],
    lines:[
      ['N','There was once a shoemaker who worked very hard, but he was getting poorer and poorer.',"Bir bor ekan, tinmay ishlaydigan bir etikdo'z bo'lgan ekan, lekin u tobora kambag'allashib borardi."],
      ['N','One evening he had enough leather for only one pair of shoes. He cut it out and went to bed.',"Bir kuni kechqurun unda faqat bir juft poyabzalga yetadigan charm qoldi. U charmni bichib, uxlashga yotdi."],
      ['N','In the morning he found a beautiful pair of shoes on the table. Every stitch was perfect.',"Ertalab u stol ustida chiroyli bir juft poyabzal topdi. Har bir chok mukammal edi."],
      ['A','Who could have made these? I\'ve never seen such fine work!',"Bularni kim tikkan bo'lishi mumkin? Bunday nozik ishni hech qachon ko'rmaganman!"],
      ['N','A customer bought them for a high price, so the shoemaker could buy leather for two pairs.',"Bir xaridor ularni qimmat narxga oldi, endi etikdo'z ikki juftga charm sotib ola oldi."],
      ['N','The next morning there were two pairs, then four, then eight. Soon the shoemaker was rich.',"Ertasiga ikki juft, keyin to'rt, keyin sakkiz juft paydo bo'ldi. Tez orada etikdo'z boyib ketdi."],
      ['B','Let\'s stay up tonight and find out who is helping us.',"Bugun kechasi uxlamay, bizga kim yordam berayotganini bilib olaylik."],
      ['N','At midnight two tiny elves came in. They had no clothes and were shivering, but they sewed and hammered until sunrise.',"Yarim tunda ikki mitti pakana kirib keldi. Ularning kiyimi yo'q edi, titrashardi, lekin quyosh chiqquncha tikib, bolg'a urib ishlashdi."],
      ['B','Those poor little men! They\'ve helped us so much. Let\'s make them some clothes.',"Bechora mitti odamchalar! Ular bizga juda ko'p yordam berishdi. Keling, ularga kiyim tikib beraylik."],
      ['N','The wife sewed tiny shirts and coats, and the shoemaker made two tiny pairs of boots.',"Xotini mitti ko'ylak va kamzullar tikdi, etikdo'z esa ikki juft mitti etik yasadi."],
      ['N','When the elves found the presents, they put them on and danced around the room with joy. Then they disappeared, but the shoemaker\'s luck stayed with him forever.',"Pakanalar sovg'alarni topib, kiyib olishdi va xursandchilikdan xona bo'ylab raqsga tushishdi. Keyin g'oyib bo'lishdi, lekin etikdo'zning omadi bir umr u bilan qoldi."]],
    qs:[['Why was the shoemaker getting poorer?',"Etikdo'z nega kambag'allashib borardi?",'Because he had little leather and few customers.'],['How did they find out about the elves?','Pakanalar haqida qanday bilib olishdi?','They stayed up at night and watched.'],['How do you thank people who help you?',"Sizga yordam berganlarga qanday minnatdorlik bildirasiz?",'I usually say thank you and help them back.']] },

  { id:'porridge', lv:'B1', t:'The Magic Porridge Pot', ic:'🍲', fun:1, focus:'had to · past perfect (had forgotten)', names:{ A:'Girl', B:'Mother', C:'Old Woman' }, g:{ A:'female', B:'female', C:'female' },
    words:[['porridge',"bo'tqa"],['while','…ayni paytda'],['forget','unutmoq'],['fill',"to'ldirmoq"],['at last','nihoyat'],['immediately','darhol'],['had to','majbur bo\'ldi']],
    lines:[
      ['N','A poor girl lived with her mother. One day in the forest, an old woman gave her a little magic pot.',"Kambag'al bir qiz onasi bilan yashardi. Bir kuni o'rmonda bir kampir unga kichkina sehrli qozon berdi."],
      ['C','When you say "Cook, little pot, cook!", it will make sweet porridge. When you say "Stop, little pot!", it will stop.',"'Pishir, qozoncha, pishir!' desang, shirin bo'tqa pishiradi. 'To'xta, qozoncha!' desang, to'xtaydi."],
      ['N','From that day the girl and her mother were never hungry.',"O'sha kundan beri qiz va onasi hech qachon och qolishmadi."],
      ['N','One morning, while the girl was out, her mother felt hungry.',"Bir kuni ertalab, qiz uyda yo'qligida, onasining qorni ochdi."],
      ['B','Cook, little pot, cook!','Pishir, qozoncha, pishir!'],
      ['N','The pot started cooking. Soon her bowl was full, but she had forgotten the magic words to stop it!',"Qozon pishira boshladi. Tez orada kosasi to'ldi, lekin u to'xtatadigan sehrli so'zlarni unutib qo'ygan edi!"],
      ['B','Enough! Finish! That\'s all! Please, no more!',"Yetarli! Bas! Bo'ldi! Iltimos, boshqa kerak emas!"],
      ['N','The porridge filled the kitchen, then the house, and then it ran out into the street.',"Bo'tqa oshxonani to'ldirdi, keyin uyni, keyin ko'chaga oqib chiqdi."],
      ['N','It filled the next house and the whole street. People had to eat their way through it!',"U qo'shni uyni va butun ko'chani to'ldirdi. Odamlar o'tish uchun bo'tqani yeb yo'l ochishga majbur bo'lishdi!"],
      ['N','At last the girl came home. She saw a river of porridge and understood immediately.',"Nihoyat qiz uyga qaytdi. U bo'tqa daryosini ko'rib, darhol tushundi."],
      ['A','Stop, little pot!',"To'xta, qozoncha!"],
      ['N','The pot stopped. But after that, anyone who wanted to come into town had to eat their way in!',"Qozon to'xtadi. Lekin shundan keyin shaharga kirmoqchi bo'lgan har kim bo'tqani yeb kirishi kerak edi!"]],
    qs:[['What were the two magic sentences?','Ikki sehrli gap qanday edi?','"Cook, little pot, cook!" and "Stop, little pot!"'],['Why couldn\'t the mother stop the pot?',"Ona nega qozonni to'xtata olmadi?",'Because she had forgotten the words.'],['What would you ask a magic pot to cook?',"Sehrli qozondan nima pishirib berishini so'ragan bo'lardingiz?",'I would ask it to cook plov every Friday.']] },

  { id:'afandi-pot', lv:'B1', t:'The Pot That Had a Baby', ic:'🫕', fun:1, focus:'could · belong to · reported belief', names:{ A:'Afandi', B:'Neighbour' }, g:{ A:'male', B:'male' },
    words:[['borrow','qarzga olmoq'],['greedy','xasis'],['return','qaytarmoq'],['belong to','…ga tegishli bo\'lmoq'],['any time','istalgan vaqt'],['ridiculous',"bema'ni"]],
    lines:[
      ['N','One day Afandi borrowed a big cooking pot from his rich neighbour. The neighbour was very greedy.',"Bir kuni Afandi boy qo'shnisidan katta qozon qarzga oldi. Qo'shni juda xasis edi."],
      ['N','A few days later Afandi returned it, and inside the big pot there was a tiny little pot.',"Bir necha kundan keyin Afandi uni qaytardi, katta qozon ichida esa mitti bir qozoncha bor edi."],
      ['B','What\'s this small pot, Afandi?','Bu kichkina qozon nima, Afandi?'],
      ['A','Good news! While your pot was at my house, it gave birth to a baby. Of course, the baby belongs to you.',"Xushxabar! Qozoningiz menikida turganda tug'ib qo'ydi. Albatta, bolasi sizniki."],
      ['N','The neighbour thought Afandi was crazy, but he happily took both pots.',"Qo'shni Afandini aqldan ozgan deb o'yladi, lekin ikkala qozonni ham xursand bo'lib oldi."],
      ['B','What a wonderful pot! Come and borrow it any time you like.',"Qanday ajoyib qozon! Xohlagan vaqtingizda kelib olavering."],
      ['N','A month later Afandi borrowed the pot again. This time weeks went by, and he didn\'t bring it back.',"Bir oydan keyin Afandi qozonni yana qarzga oldi. Bu safar haftalar o'tdi, lekin u qozonni qaytarmadi."],
      ['B','Afandi, where\'s my pot? I need it for a wedding.',"Afandi, qozonim qani? To'y uchun kerak."],
      ['A','I\'m very sorry to tell you this... your poor pot has died.',"Buni aytishga juda afsusdaman... bechora qozoningiz vafot etdi."],
      ['B','Died?! Don\'t be ridiculous! A pot can\'t die!',"Vafot etdi?! Bema'ni gapirmang! Qozon o'lmaydi-ku!"],
      ['A','Strange. You believed that a pot could have a baby, but you can\'t believe that it can die?',"G'alati. Qozon tug'ishiga ishondingiz-u, o'lishiga ishonolmaysizmi?"],
      ['N','The greedy neighbour had nothing to say. And Afandi cooked plov in that pot for many years.',"Xasis qo'shni hech narsa deya olmadi. Afandi esa ko'p yillar o'sha qozonda palov damladi."]],
    qs:[['What did Afandi return the first time?','Afandi birinchi safar nimani qaytardi?','The big pot with a tiny pot inside.'],['Why did the neighbour believe the first story?',"Qo'shni nega birinchi gapga ishondi?",'Because he was greedy and got a free pot.'],['What is the funniest Afandi story you know?',"Siz bilgan eng kulgili Afandi latifasi qaysi?",'I like the story where Afandi feeds his coat.']] },

  /* ---------------- B2 ---------------- */
  { id:'fisher', lv:'B2', t:'The Fisherman and His Wife', ic:'🐟', focus:'would · as if + past perfect', names:{ A:'Fisherman', B:'Wife', C:'Fish' }, g:{ A:'male', B:'female', C:'male' },
    words:[['miserable','ayanchli'],['astonishment','hayrat'],['release',"qo'yib yubormoq"],['grant a wish','tilakni bajarmoq'],['dissatisfied','norozi'],['deserve',"loyiq bo'lmoq"],['furious',"g'azabli"],['as if',"go'yo"]],
    lines:[
      ['N','A poor fisherman lived with his wife in a miserable little hut by the sea.',"Kambag'al bir baliqchi xotini bilan dengiz bo'yidagi ayanchli kulbada yashardi."],
      ['N','One day he caught an enormous fish, which, to his astonishment, began to speak.',"Bir kuni u ulkan baliq tutdi va baliq, uni hayratda qoldirib, gapira boshladi."],
      ['C','Please let me go. I\'m not really a fish; I\'m an enchanted prince. I\'d taste terrible anyway.',"Iltimos, meni qo'yib yuboring. Men aslida baliq emas, sehrlangan shahzodaman. Baribir ta'mim dahshatli bo'lardi."],
      ['N','The kind-hearted fisherman released it without asking for anything in return.',"Ko'ngilchan baliqchi evaziga hech narsa so'ramay, uni qo'yib yubordi."],
      ['B','You let a magic fish go and didn\'t even make a wish? Go back at once and ask for a proper cottage!',"Sehrli baliqni qo'yib yuborib, hatto tilak ham tilamadingmi? Darhol qaytib bor-da, durustroq uy so'ra!"],
      ['N','The fish granted the wish. But within a week the wife was dissatisfied again.',"Baliq tilakni bajardi. Lekin bir hafta o'tmay xotin yana norozi bo'lib qoldi."],
      ['B','A cottage? Don\'t be absurd. I deserve a stone castle with servants!',"Uycha? Bema'ni gap. Men xizmatkorlari bor tosh qal'aga loyiqman!"],
      ['N','Then she wanted to be queen, then empress. Each time, the sea grew darker and the waves grew higher.',"Keyin u qirolicha, so'ng imperatritsa bo'lishni xohladi. Har safar dengiz qorayib, to'lqinlar balandlashib borardi."],
      ['B','I want to control the sun and the moon. Tell the fish to make me ruler of the whole universe!',"Men quyosh va oyni boshqarmoqchiman. Baliqqa ayt, meni butun olamning hukmdori qilsin!"],
      ['N','The terrified fisherman went down to the shore. A furious storm was raging.',"Qo'rqib ketgan baliqchi qirg'oqqa tushdi. Shiddatli bo'ron avjiga chiqqan edi."],
      ['C','Go home. She is back where she started.',"Uyingga qayt. U boshlagan joyiga qaytdi."],
      ['N','And there was his wife, sitting in the same miserable little hut, as if nothing had ever happened.',"Mana, xotini o'sha ayanchli kulbada o'tiribdi, go'yo hech narsa bo'lmagandek."]],
    qs:[['How did the wife change after each wish?',"Har bir tilakdan keyin xotin qanday o'zgardi?",'She became more and more greedy.'],['Why did the sea grow darker each time?',"Nega har safar dengiz qorayib borardi?",'It showed that the fish was getting angry.'],['Is it possible to be satisfied with what you have? Explain.',"Bor narsaga qanoat qilish mumkinmi? Tushuntiring.",'I think so, if you focus on what really matters, like family and health.']] },

  { id:'rumpel', lv:'B2', t:'Rumpelstiltskin', ic:'🧵', focus:'First conditional · had nothing left', names:{ A:'Queen', B:'Little Man', C:'King' }, g:{ A:'female', B:'male', C:'male' },
    words:[['boastful','maqtanchoq'],['spin','yigirmoq'],['have no idea','umuman bilmaslik'],['desperate','umidsiz'],['agree',"rozi bo'lmoq"],['guess','topmoq (taxmin)'],['within','…ichida']],
    lines:[
      ['N','A boastful miller once told the king that his daughter could spin straw into gold.',"Maqtanchoq bir tegirmonchi qirolga qizi somonni oltinga aylantira olishini aytdi."],
      ['C','If that\'s true, she\'ll become my wife. If it\'s a lie, she\'ll be in serious trouble.',"Agar bu rost bo'lsa, u xotinim bo'ladi. Yolg'on bo'lsa, boshiga katta kulfat tushadi."],
      ['N','The girl was locked in a room full of straw. She sat down and wept, because she had no idea how to do it.',"Qizni somonga to'la xonaga qamashdi. U o'tirib yig'ladi, chunki buni qanday qilishni umuman bilmasdi."],
      ['B','What will you give me if I spin it for you?',"Agar sen uchun yigirib bersam, menga nima berasan?"],
      ['N','A strange little man spun all the straw into gold, first for her necklace, then for her ring.',"G'alati pakana hamma somonni oltinga aylantirdi: avval marjoni, keyin uzugi evaziga."],
      ['N','On the third night she had nothing left to give.',"Uchinchi kechasi unda beradigan hech narsa qolmadi."],
      ['B','Then promise me your first child when you are queen.',"Unda qirolicha bo'lganingda birinchi farzandingni menga berishga va'da ber."],
      ['N','Desperate, she agreed. The king married her, and a year later she had a beautiful baby.',"Iloji qolmagan qiz rozi bo'ldi. Qirol unga uylandi, bir yildan so'ng u go'zal chaqaloq ko'rdi."],
      ['B','I\'ve come for what you promised me. But I\'ll make you a deal: if you can guess my name within three days, you may keep the child.',"Va'da qilgan narsangni olgani keldim. Lekin bir shart: uch kun ichida ismimni topsang, bola senda qoladi."],
      ['N','On the last night, a messenger saw the little man dancing around a fire and singing: "Nobody knows my name is Rumpelstiltskin!"',"Oxirgi kechasi bir chopar pakananing gulxan atrofida raqsga tushib kuylayotganini ko'rdi: 'Hech kim bilmaydi, ismim Rumpelshtilsxen!'"],
      ['A','Is your name, perhaps... Rumpelstiltskin?',"Ismingiz, balki... Rumpelshtilsxendir?"],
      ['N','The little man was so furious that he stamped his foot right through the floor and was never seen again.',"Pakana shunchalik g'azablandiki, oyog'ini polga urib teshib yubordi va boshqa hech qachon ko'rinmadi."]],
    qs:[['Why was the girl in trouble?',"Qiz nega qiyin ahvolga tushdi?",'Because her father boasted that she could spin straw into gold.'],['How did the queen learn the name?',"Qirolicha ismni qanday bilib oldi?",'A messenger heard the little man singing it.'],['Have you ever promised something and regretted it?',"Biror narsaga va'da berib, keyin afsuslanganmisiz?",'Yes, I once promised to finish a project in a week, which was unrealistic.']] },

  { id:'piper', lv:'B2', t:'The Pied Piper of Hamelin', ic:'🎶', focus:'It was … who (cleft) · regret + -ing', names:{ A:'Mayor', B:'Piper' }, g:{ A:'male', B:'male' },
    words:[['get rid of','…dan qutulmoq'],['mysterious','sirli'],['appear',"paydo bo'lmoq"],['give your word',"so'z bermoq"],['tune','kuy'],['regret','afsuslanmoq'],['keep a promise',"va'dani bajarmoq"]],
    lines:[
      ['N','In the year 1284 the town of Hamelin had a terrible problem: rats. They were everywhere, in kitchens, in cradles, even in the mayor\'s hat.',"1284-yilda Hamelin shahrida dahshatli muammo bor edi: kalamushlar. Ular hamma joyda edi: oshxonada, beshikda, hatto hokimning shlyapasida ham."],
      ['A','Something must be done! I\'ll pay a thousand gold coins to anyone who gets rid of them.',"Nimadir qilish kerak! Ulardan qutqargan odamga ming oltin tanga to'layman."],
      ['N','The next day a mysterious stranger appeared, dressed in a coat of red and yellow, with a small pipe.',"Ertasiga qizil-sariq to'n kiygan, qo'lida kichkina nay bor sirli notanish paydo bo'ldi."],
      ['B','I can rid your town of every single rat. Do we have a deal?',"Shahringizni har bir kalamushdan xalos qila olaman. Kelishdikmi?"],
      ['A','Absolutely. You have my word.',"Albatta. So'z beraman."],
      ['N','The piper began to play a strange, sweet tune. Rats poured out of every house and followed him to the river, where they all drowned.',"Naychi g'alati, shirin kuy chala boshladi. Kalamushlar har bir uydan oqib chiqib, uning ortidan daryoga ergashdi va hammasi cho'kib ketdi."],
      ['B','The job is done. Now, my thousand coins, please.',"Ish bajarildi. Endi ming tangamni bering."],
      ['A','A thousand? For playing a little tune? Here\'s fifty. Take it or leave it.',"Mingta? Bir kuy chalganing uchunmi? Mana ellikta. Olsang ol, olmasang yo'q."],
      ['B','You\'ll regret breaking your promise.',"Va'dangizni buzganingizdan afsuslanasiz."],
      ['N','He raised his pipe and played a new melody. This time it was the children who came running, laughing and dancing behind him.',"U naychasini ko'tarib, yangi kuy chaldi. Bu safar uning ortidan kulib, raqsga tushib yugurib kelganlar bolalar edi."],
      ['N','He led them into the mountains, where a door opened in the rock. They all went inside, and the door closed behind them.',"U ularni tog'larga olib bordi, qoyada eshik ochildi. Hammasi ichkariga kirdi va eshik ortlaridan yopildi."],
      ['N','Only one boy, who couldn\'t keep up, came back to tell the story. Since that day, Hamelin has always kept its promises.',"Faqat yetib ololmagan bir bola qaytib kelib, voqeani aytib berdi. O'sha kundan beri Hamelin doim va'dasiga vafo qiladi."]],
    qs:[['What did the mayor promise?',"Hokim nimani va'da qildi?",'A thousand gold coins to anyone who got rid of the rats.'],['Why did the piper take the children?',"Naychi nega bolalarni olib ketdi?",'Because the mayor broke his promise.'],['Why is keeping promises important in business?',"Biznesda va'dani bajarish nega muhim?",'Because trust is hard to build and easy to lose.']] },

  { id:'goose', lv:'B2', t:'The Golden Goose', ic:'🪿', fun:1, focus:'whoever · the moment … · may be', names:{ A:'Hans', B:'Princess', C:'King' }, g:{ A:'male', B:'female', C:'male' },
    words:[['consider','hisoblamoq'],['share',"baham ko'rmoq"],['in return','evaziga'],['resist','chidab turmoq'],['get stuck','yopishib qolmoq'],['meanwhile','bu orada'],['stumble','qoqilmoq'],['impressive',"ta'sirli"]],
    lines:[
      ['N','There was once a young man called Hans, whom everyone considered a fool. His older brothers never shared anything with him.',"Bir bor ekan, hamma ahmoq deb hisoblaydigan Hans ismli yigit bo'lgan ekan. Akalari u bilan hech narsani baham ko'rishmasdi."],
      ['N','One day in the forest he shared his dry bread with a hungry old man. In return, the old man showed him a tree with a goose of pure gold under it.',"Bir kuni o'rmonda u quruq nonini och chol bilan baham ko'rdi. Evaziga chol unga tagida sof oltin g'oz turgan daraxtni ko'rsatdi."],
      ['N','Hans took the goose and stayed the night at an inn. The innkeeper\'s daughter couldn\'t resist taking a golden feather, but the moment she touched it, her hand got stuck.',"Hans g'ozni olib, karvonsaroyda tunadi. Karvonsaroy egasining qizi oltin pat olishga chiday olmadi, lekin tegishi bilan qo'li yopishib qoldi."],
      ['N','Her sister tried to pull her free and got stuck to her. Then a teacher, a farmer and a baker all got stuck in a long, ridiculous line.',"Singlisi uni tortib ajratmoqchi bo'ldi va o'zi ham yopishib qoldi. Keyin o'qituvchi, dehqon va novvoy ham uzun, kulgili qatorga yopishib qolishdi."],
      ['N','Meanwhile, in the city, there lived a princess so serious that she had never laughed in her life.',"Bu orada shaharda umrida bir marta ham kulmagan juda jiddiy malika yashardi."],
      ['C','Whoever makes my daughter laugh shall marry her!',"Qizimni kuldirgan kishi unga uylanadi!"],
      ['N','Hans marched past the palace with his goose, followed by seven people stuck together, shouting, stumbling and complaining.',"Hans g'ozi bilan saroy yonidan o'tdi, ortidan bir-biriga yopishgan yetti kishi baqirib, qoqilib, nolib kelardi."],
      ['B','Ha... ha ha... HA HA HA! Look at them! I can\'t stop laughing!',"Ha... ha-ha... HA-HA-HA! Ularga qarang! Kulgimni to'xtatolmayapman!"],
      ['C','Well... a promise is a promise. Though I must say, I expected someone a bit more impressive.',"Xo'sh... va'da — va'da. Lekin tan olay, men biroz ta'sirliroq odamni kutgandim."],
      ['A','Don\'t worry, Your Majesty. I may be simple, but I\'m kind, and I\'ll make her laugh every day.',"Xavotir olmang, hazratim. Men oddiy bo'lishim mumkin, lekin mehribonman va uni har kuni kuldiraman."],
      ['N','And so the "fool" married the princess, and the people who were stuck were finally set free... after the wedding feast, of course.',"Shunday qilib 'ahmoq' yigit malikaga uylandi, yopishib qolganlar esa nihoyat ozod qilindi... albatta, to'y ziyofatidan keyin."]],
    qs:[['Why did the old man help Hans?','Chol nega Hansga yordam berdi?','Because Hans shared his bread with him.'],['What made the princess laugh?','Malikani nima kuldirdi?','Seven people stuck to a golden goose, stumbling and shouting.'],['Is kindness more important than being clever? Why?',"Mehribonlik aqllilikdan muhimroqmi? Nega?",'I think kindness opens more doors in the long run.']] },

  { id:'afandi-smell', lv:'B2', t:'The Price of a Smell', ic:'💰', fun:1, focus:'Present perfect continuous · passive (must be paid)', names:{ A:'Afandi', B:'Cook', C:'Poor Man' }, g:{ A:'male', B:'male', C:'male' },
    words:[['steam',"bug'"],['soften','yumshatmoq'],['owe','qarzdor bo\'lmoq'],['argument','janjal, bahs'],['settle','hal qilmoq'],['justice','adolat'],['receive','olmoq'],['fair','adolatli']],
    lines:[
      ['N','One cold morning a poor man was standing outside a cook\'s shop, warming his hands over the steam rising from a pot of soup.',"Bir sovuq tongda kambag'al bir odam oshpaz do'koni oldida, qozondan ko'tarilayotgan sho'rva bug'ida qo'llarini isitib turardi."],
      ['N','He held his dry bread over the steam to soften it, and ate it slowly.',"U quruq nonini yumshatish uchun bug' ustida tutib, sekin yedi."],
      ['B','Hey! You\'ve been enjoying the smell of my soup. You owe me money for that!',"Hoy! Sen sho'rvamning hididan rohatlanding. Buning uchun menga pul qarzsan!"],
      ['C','Pay for a smell? I didn\'t eat anything of yours!',"Hid uchun pul to'laymanmi? Sizning hech narsangizni yemadim-ku!"],
      ['N','The argument got louder and louder, until they agreed to let Afandi, who happened to be the judge that day, settle the matter.',"Janjal tobora kuchaydi, oxiri ular o'sha kuni tasodifan qozi bo'lgan Afandiga masalani hal qildirishga kelishishdi."],
      ['A','Hmm. So you\'re saying that the smell of your soup has value?',"Hmm. Demak, sho'rvangizning hidi qimmatga ega demoqchisiz?"],
      ['B','Of course it does! It took me hours to make that soup.',"Albatta! U sho'rvani pishirishga soatlab vaqt ketdi."],
      ['A','Very well. Then justice must be done. You, poor man, give me your purse.',"Juda yaxshi. Unda adolat qaror topishi kerak. Siz, bechora, hamyoningizni bering."],
      ['N','Afandi took the few coins from the purse and shook them right next to the cook\'s ear. Clink, clink, clink.',"Afandi hamyondagi bir necha tangani olib, oshpazning qulog'i yonida silkitdi. Jiring, jiring, jiring."],
      ['A','There. You have been paid.',"Mana. Sizga to'landi."],
      ['B','Paid? I haven\'t received a single coin!',"To'landimi? Bitta ham tanga olganim yo'q-ku!"],
      ['A','It\'s perfectly fair. A man who sells the smell of food must be paid with the sound of money.',"Bu mutlaqo adolatli. Ovqat hidini sotgan odamga pulning ovozi bilan to'lanadi."]],
    qs:[['Why did the cook want money?',"Oshpaz nega pul so'radi?",'Because the poor man enjoyed the smell of his soup.'],['How did Afandi "pay" the cook?',"Afandi oshpazga qanday 'to'ladi'?",'He let him hear the sound of the coins.'],['Do you think Afandi\'s decision was fair? Why?',"Afandining qarori adolatli bo'ldimi? Nega?",'Yes, because the cook asked for something unfair, so he got an equal answer.']] }
  ];

