  const TUNE_NOTE = { C:0, D:2, E:4, F:5, G:7, A:9, B:11 };
  /* "C#4:1.5" -> { f: frequency, d: beats } */
  function parseNotes(s){
    return String(s || '').trim().split(/\s+/).filter(Boolean).map(tok => {
      const [n, d] = tok.split(':'); const m = /^([A-G])([#b]?)(\d)$/.exec(n);
      if (!m) return { f: 0, d: +d || 1 };
      const midi = 12 * (+m[3] + 1) + TUNE_NOTE[m[1]] + (m[2] === '#' ? 1 : m[2] === 'b' ? -1 : 0);
      return { f: 440 * Math.pow(2, (midi - 69) / 12), d: d ? +d : 1 };
    });
  }
  return { TALES, SONGS, POP, parseNotes };
